//! 自作整数解に目的上限制約を加えて既存Repairだけで改善を試す独立診断。
use mip_codex::{heuristic::Repair,model::{Model,Row},solve::Result};
use std::{fs::File,time::{Instant,Duration}};
fn main(){let a:Vec<_>=std::env::args().collect();let m:Model=if a[1].ends_with(".json"){serde_json::from_reader(File::open(&a[1]).unwrap()).unwrap()}else{mip_codex::mps::read(&a[1]).unwrap()};assert!(!m.maximize&&m.offset==0.&&m.variables.iter().all(|v|v.integer&&v.lower==Some(0.)&&v.upper==Some(1.)&&v.objective==1.));let seed:serde_json::Value=serde_json::from_reader(File::open(&a[2]).unwrap()).unwrap();let vals=&seed["values"];let mut x:Vec<_>=m.variables.iter().map(|v|vals[&v.name].as_f64().unwrap()).collect();assert!(Repair::new(&m).candidate_check(&x));let start=Instant::now();let seconds:f64=a[3].parse().unwrap();let end=start+Duration::from_secs_f64(seconds);let mut records=Vec::new();let mut turn=0;
while Instant::now()<end{let mut work:Model=m.clone();let target=m.objective(&x)-1.;work.rows.push(Row {integer_bounds:None,name:"diagnostic_objective_cut".into(),lower:None,upper:Some(target),coefficients:(0..m.variables.len()).map(|j|(j,1.)).collect(),exact_integral:true,exact_coefficients:true,exact_coefficient_flags:Vec::new(),lower_enclosure:None,upper_enclosure:Some([target,target])});let lower:Vec<_>=m.variables.iter().map(|v|v.lower).collect();let upper:Vec<_>=m.variables.iter().map(|v|v.upper).collect();let mut repair=Repair::new(&work);let deadline=end.min(Instant::now()+Duration::from_millis(500));let trial_point:Vec<_>=x.iter().map(|&v|if turn<2{v}else if v>0.5{0.95}else{0.001}).collect();let trial=repair.search(&trial_point,&lower,&upper,deadline,100_000_000,turn);records.push(serde_json::json!({"target":target,"found":trial.is_some(),"work":repair.stats.work,"seconds":start.elapsed().as_secs_f64()}));if let Some(v)=trial{assert!(Repair::new(&m).candidate_check(&v));assert!(m.objective(&v)<m.objective(&x));x=v;}turn+=1;}
let r=Result{status:"feasible_objective_cut_diagnostic".into(),objective:Some(m.objective(&x)),values:Some(m.variables.iter().zip(&x).map(|(v,&x)|(v.name.clone(),x)).collect()),seconds:start.elapsed().as_secs_f64(),..Result::default()};serde_json::to_writer(File::create(&a[4]).unwrap(),&r).unwrap();println!("{}",serde_json::json!({"objective":r.objective,"seconds":r.seconds,"records":records}));}
